    lines = f.read().strip().split("\n")
seq = "".join(lines[1:]).upper()

bases = "TCAG"
aas = "FFLLSSSSYYYYCCWWLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG"
codon_table = {}
i = 0
for b1 in bases:
    for b2 in bases:
        for b3 in bases:
            codon_table[b1+b2+b3] = aas[i]; i += 1

comp = str.maketrans("ACGT", "TGCA")
rev = seq.translate(comp)[::-1]
L = len(seq)

def orfs_on(strand, min_aa=50):
    s = seq if strand == "+" else rev
    out = []
    for frame in range(3):
        starts = []
        for i in range(0, (L - frame)//3 + 0):
            p = frame + i*3
            if p + 3 > L: break
            aa = codon_table[s[p:p+3]]
            if aa == "M":
                starts.append(i)
            elif aa == "*":
                for st in starts:
                    n = i - st
                    if n >= min_aa:
                        prot = "".join(codon_table[s[frame+st*3+3*x]] for x in range(n))
                        if strand == "+":
                            cs, ce = frame+st*3+1, frame+i*3+3
                        else:
                            cs, ce = L-(frame+i*3+3)+1, L-(frame+st*3+1)
                        out.append((strand, frame+1, cs, ce, prot))
                starts = []
    return out

res = orfs_on("+") + orfs_on("-")
res.sort(key=lambda r: -(r[4]-r[3]))
