def translate(s):
    return "".join(codon_table[s[i:i+3]] for i in range(0, len(s)-2, 3))

def orfs(strand, min_aa=50):
    s = seq if strand == "+" else seq.translate(str.maketrans("ACGT","TGCA"))[::-1]
    out = []
    for frame in range(3):
        prot = translate(s[frame:])
        starts = []
        for i, aa in enumerate(prot):
            if aa == "M":
                starts.append(i)
            elif aa == "*":
                for st in starts:
                    if i - st >= min_aa:
                        p = prot[st:i]
                        if strand == "+":
                            cs = frame + st*3 + 1
                            ce = frame + (i-1)*3 + 3
                        else:
                            cs = L - (frame + i*3 + 3) + 1
                            ce = L - (frame + (i-1)*3 + 3)
                        out.append((strand, frame+1, cs, ce, p))
                starts = []
    return out

res = orfs("+") + orfs("-")
res.sort(key=lambda r: -(len(r[4])))
